INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ($txt$e7111111-1111-4111-8111-111111111111$txt$::uuid, $txt$TUT-BAHASA13-001$txt$, $txt$b6666666-6666-6666-6666-666666666666$txt$::uuid, $txt$Bahasa Turki: Sapaan Dasar$txt$, $txt$tut-bahasa-turki-sapaan-dasar$txt$, $txt$Kuasai sapaan dasar bahasa Turki dalam 7 hari: pengucapan huruf khusus, 10 sapaan penting, dan kesalahan umum pemula.$txt$, 'id', 8, $txt$Madevi$txt$, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid) ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Ingin Menyapa dalam Bahasa Turki tapi Takut Salah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Banyak orang Indonesia tertarik dengan Turki — dramanya, wisatanya, beasiswanya — tetapi urung belajar bahasanya karena mengira sulit. Padahal sapaan dasar bahasa Turki bisa dikuasai dalam satu sore saja.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Bahasa Turki Lebih Mudah dari Dugaan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Bahasa Turki memakai alfabet Latin dengan 29 huruf dan pengucapan yang hampir selalu konsisten (dibaca apa adanya). Tidak ada perbedaan gender kata seperti bahasa Arab atau Prancis, dan struktur kalimatnya teratur. Tantangan utamanya hanya beberapa huruf khusus: ç dibaca seperti c pada kata cello, ş dibaca sy, ğ hampir tidak berbunyi dan memanjangkan vokal sebelumnya, serta perbedaan İ (i bertitik, bunyi i) dan I (tanpa titik, bunyi seperti e pepet).$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Perlu Disiapkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', $txt$["Aplikasi kamus Turki-Indonesia atau Google Translate (unduh paket offline bahasa Turki)", "Buku catatan kecil untuk menulis sapaan beserta cara bacanya", "Video atau audio penutur asli dari kanal belajar bahasa Turki untuk pemula", "Cermin atau perekam suara HP untuk latihan pengucapan"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Kuasai 10 Sapaan Dasar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', $txt$["Merhaba (mer-ha-ba) — Halo, sapaan umum paling aman", "Günaydın (gu-na-i-dun) — Selamat pagi", "İyi günler (i-yi gun-ler) — Selamat siang", "İyi akşamlar (i-yi ak-syam-lar) — Selamat malam", "Teşekkürler (te-syek-kur-ler) — Terima kasih", "Lütfen (lut-fen) — Tolong / silakan", "Evet (e-vet) — Ya; Hayır (ha-yur) — Tidak", "Nasılsın? (na-sul-sun) — Apa kabar? (informal, ke teman sebaya)", "Hoşça kal (hosy-ca kal) — Selamat tinggal (diucapkan oleh yang pergi)", "Özür dilerim (o-zur di-le-rim) — Maaf"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko: Kesalahan Umum Pemula$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', $txt$["Tertukar İ dan I sehingga arti kata berubah — latih telinga dengan audio penutur asli", "Mengucapkan ğ seperti g keras, padahal ğ hampir bisu (misalnya dağ dibaca daa)", "Memakai sapaan informal kepada orang yang lebih tua — gunakan bentuk sopan", "Hafal tulisan tetapi tidak pernah bersuara — bahasa adalah bunyi, wajib dilafalkan"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian: Checklist 7 Hari$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', $txt$["Hari 1–2: hafal 5 sapaan pertama beserta cara bacanya", "Hari 3–4: tambah 5 sapaan sisanya, latih di depan cermin", "Hari 5: rekam suara sendiri lalu bandingkan dengan audio penutur asli", "Hari 6: tulis dialog mini 4 baris memakai sapaan yang dipelajari", "Hari 7: praktikkan ke teman atau komunitas belajar bahasa Turki daring"]$txt$::jsonb));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ($txt$e7122222-2222-4222-8222-222222222222$txt$::uuid, $txt$TUT-KESEHATAN26-001$txt$, $txt$b5555555-5555-5555-5555-555555555555$txt$::uuid, $txt$Kuku Rapuh: Perawatan di Rumah$txt$, $txt$tut-kuku-rapuh-perawatan$txt$, $txt$Atasi kuku mudah patah dan terkelupas dengan perawatan rumahan: penyebab, langkah perawatan, dan tanda bahaya yang perlu ke dokter.$txt$, 'id', 7, $txt$Madevi$txt$, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid) ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Kuku Mudah Patah dan Terkelupas$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Kuku yang rapuh, mudah patah, terkelupas berlapis, atau bergaris membuat tangan terlihat tidak terawat dan kadang terasa nyeri. Penyebabnya beragam: sering terkena air dan sabun, kekurangan nutrisi, kebiasaan menggigit kuku, hingga kondisi medis tertentu.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Mengapa Kuku Menjadi Rapuh$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Kuku terbuat dari keratin, protein yang sama pembentuk rambut. Kuku rapuh terjadi ketika lapisan keratin kehilangan kelembapan dan kekuatan. Pemicu umum: terlalu sering mencuci tangan tanpa pelembap, paparan deterjen, kuteks dan penghapus berbahan aseton yang dipakai berlebihan, kekurangan zat besi atau biotin, penuaan, serta kondisi seperti hipotiroidisme atau psoriasis kuku.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Alat dan Bahan yang Perlu Disiapkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', $txt$["Gunting kuku dan kikir kuku yang bersih", "Pelembap tangan atau kuku, atau minyak alami seperti minyak zaitun dan minyak kelapa", "Sarung tangan karet untuk mencuci piring", "Penguat kuku (nail hardener) bila diperlukan"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah: Perawatan Kuku Rapuh di Rumah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', $txt$["Potong kuku secara rutin dan jangan terlalu pendek; kikir searah agar lapisan tidak terangkat", "Oleskan pelembap atau minyak ke kuku dan kutikula setiap selesai cuci tangan dan sebelum tidur", "Pakai sarung tangan karet setiap mencuci piring atau memakai deterjen", "Batasi pemakaian kuteks; beri jeda beberapa hari dan hindari penghapus berbahan aseton keras", "Jangan menggigit kuku dan jangan mencungkil kutikula — dorong perlahan bila perlu", "Perbaiki pola makan: cukup protein, zat besi (bayam, hati, kacang-kacangan), dan biotin (telur, kacang)"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Hal yang Perlu Diwaspadai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', $txt$["Perubahan warna kuku (menguning, menghitam), penebalan, atau bau tidak sedap bisa menandakan infeksi jamur", "Kuku sangat rapuh disertai rambut rontok dan mudah lelah dapat berkaitan dengan anemia atau gangguan tiroid", "Jangan mengonsumsi suplemen dosis tinggi tanpa anjuran dokter", "Informasi ini bersifat umum dan bukan pengganti nasihat medis"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian: Evaluasi dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', $txt$["Terapkan perawatan rutin selama 4–6 minggu; foto kuku tiap 2 minggu untuk melihat perubahan", "Konsultasikan ke dokter atau dokter kulit bila kuku berubah warna, menebal, terlepas, nyeri, atau bernanah", "Periksakan diri bila kerapuhan tidak membaik setelah 2–3 bulan perawatan rutin", "Bila disertai kelelahan berat atau rambut rontok parah, diskusikan kemungkinan anemia atau gangguan tiroid dengan dokter"]$txt$::jsonb));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ($txt$e7133333-3333-4333-8333-333333333333$txt$::uuid, $txt$EXP-GEOGRAFI13-001$txt$, $txt$c6000001-0000-0000-0000-000000000001$txt$::uuid, $txt$Gurun Terbesar di Dunia$txt$, $txt$exp-gurun-terbesar-di-dunia$txt$, $txt$Mengenal gurun-gurun terbesar di dunia: dari Gurun Antartika yang beku hingga Sahara yang panas, lengkap dengan luas dan cirinya.$txt$, 'id', 6, $txt$Madevi$txt$, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid) ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Apa Itu Gurun?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Gurun adalah wilayah yang menerima curah hujan sangat sedikit — umumnya kurang dari 250 mm per tahun. Banyak orang membayangkan gurun selalu panas dan berpasir, padahal gurun terbesar di dunia justru dingin dan tertutup es.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$1. Gurun Antartika — Terbesar di Dunia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Dengan luas sekitar 14 juta kilometer persegi, Gurun Kutub Antartika adalah gurun terbesar di dunia. Ia disebut gurun karena hampir tidak ada curah hujan — airnya terkunci sebagai es. Suhu di sini bisa turun hingga minus 80 derajat Celsius.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$2. Gurun Arktik — Raksasa di Utara$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Gurun kutub di sekitar Kutub Utara mencakup sekitar 13,9 juta kilometer persegi. Wilayahnya berupa tundra es dan lautan beku, menjadi rumah bagi beruang kutub, rubah Arktik, dan masyarakat Inuit.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$3. Gurun Sahara — Gurun Panas Terbesar$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Sahara di Afrika Utara seluas sekitar 9,2 juta kilometer persegi — hampir seluas Amerika Serikat. Suhu siangnya bisa melebihi 50 derajat Celsius, tetapi malam harinya bisa mendekati 0 derajat. Sahara bukan sekadar hamparan pasir; sebagian besarnya berupa dataran batu dan kerikil.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$4. Gurun Arab dan Gurun Gobi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Gurun Arab seluas sekitar 2,3 juta kilometer persegi menutupi sebagian besar Semenanjung Arab dengan bukit-bukit pasir raksasanya. Gurun Gobi di Mongolia dan Tiongkok (sekitar 1,3 juta km persegi) adalah gurun dingin — terkenal sebagai lokasi penemuan fosil dinosaurus dan musim dingin yang ekstrem.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ($txt$e7144444-4444-4444-8444-444444444444$txt$::uuid, $txt$EXP-TEKNOLOGI15-001$txt$, $txt$c7777777-7777-7777-7777-777777777777$txt$::uuid, $txt$Smartphone: Evolusi 30 Tahun$txt$, $txt$exp-smartphone-evolusi-30-tahun$txt$, $txt$Perjalanan 30 tahun smartphone: dari IBM Simon 1994, era Nokia, BlackBerry, iPhone, hingga Android dan 5G.$txt$, 'id', 6, $txt$Madevi$txt$, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid) ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Awal Mula: IBM Simon (1994)$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Smartphone pertama di dunia, IBM Simon, diluncurkan tahun 1994 — bisa menelepon, mengirim email dan faks, dengan layar sentuh monokrom. Harganya 899 dolar AS dan baterainya hanya tahan sekitar satu jam.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Era Nokia dan Ponsel Fitur (Awal 2000-an)$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Nokia 3310 (tahun 2000) dan ponsel fitur merajai dunia dengan daya tahan baterai berhari-hari dan permainan Snake yang legendaris. Fungsi utama ponsel saat itu masih menelepon dan SMS.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$BlackBerry: Ponsel Pebisnis (2003–2010)$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$BlackBerry mempopulerkan keyboard QWERTY fisik dan layanan email push. Di Indonesia, BBM (BlackBerry Messenger) sempat menjadi aplikasi chat paling populer sebelum era WhatsApp tiba.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Titik Balik: iPhone (2007)$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Steve Jobs memperkenalkan iPhone pertama pada tahun 2007 — layar sentuh penuh tanpa keyboard fisik, disusul App Store setahun kemudian. Inilah cetak biru smartphone modern yang kita kenal sekarang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Android dan Perang Ekosistem (2008–Sekarang)$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Android (2008) membuka pasar lewat banyak merek: Samsung, Xiaomi, Oppo, Vivo. Persaingan iOS melawan Android mendorong inovasi tanpa henti: kamera ganda, sidik jari, pengisian cepat, layar lipat, kecerdasan buatan, hingga konektivitas 5G.$txt$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ($txt$e7155555-5555-4555-8555-555555555555$txt$::uuid, $txt$SCH-SMP-ING9-001$txt$, $txt$d4444444-4444-4444-4444-444444444444$txt$::uuid, $txt$Bahasa Inggris Kelas 7: Procedure Text$txt$, $txt$sch-smp-ing9-procedure-text$txt$, $txt$Materi procedure text kelas 7: pengertian, struktur goal-materials-steps, ciri kebahasaan, contoh resep, latihan, dan kunci jawaban.$txt$, 'id', 10, $txt$Madevi$txt$, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid) ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) mengidentifikasi tujuan dan struktur procedure text, (2) menggunakan imperative sentence dan action verbs dengan tepat, (3) menulis procedure text sederhana seperti resep atau petunjuk.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Procedure Text$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Procedure text adalah teks yang menjelaskan cara membuat atau melakukan sesuatu melalui langkah-langkah yang berurutan. Contohnya: resep masakan, petunjuk merakit mainan, atau cara mengoperasikan alat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Struktur Procedure Text$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', $txt$["Goal atau Aim: tujuan — apa yang akan dibuat atau dilakukan (misalnya How to Make Fried Rice)", "Materials atau Ingredients: bahan-bahan dan alat yang dibutuhkan", "Steps: langkah-langkah berurutan yang memakai imperative sentence"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Ciri Kebahasaan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', $txt$["Imperative sentence: Cut the onion. Boil the water. (tanpa subjek)", "Action verbs: cut, pour, mix, stir, add, boil", "Kata penghubung urutan: first, second, then, next, after that, finally", "Simple present tense"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Contoh: How to Make Instant Noodles$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Goal: How to Make Instant Noodles. Ingredients: one pack of instant noodles, 400 ml of water, an egg (optional). Steps: First, boil 400 ml of water in a pan. Second, add the noodles and cook them for three minutes. Next, add the seasoning and stir well. Finally, serve the noodles in a bowl. Enjoy your meal!$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', $txt$["Susun langkah acak berikut menjadi procedure text yang benar: serve the tea — boil the water — pour the water into the cup — add the tea bag", "Tulis procedure text berjudul How to Make a Glass of Orange Juice minimal 5 langkah", "Lingkari imperative verbs pada kalimat: First, wash the apples. Then, cut them into pieces.", "Kunci jawaban: (1) boil the water — add the tea bag — pour the water into the cup — serve the tea. (2) Contoh: First, peel two oranges. Second, cut them into pieces. Next, put the pieces into a juicer. Then, add some ice cubes. Finally, pour the juice into a glass. (3) wash, cut."]$txt$::jsonb));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ($txt$e7166666-6666-4666-8666-666666666666$txt$::uuid, $txt$SCH-SD-MAT18-001$txt$, $txt$d1000002-0000-0000-0000-000000000002$txt$::uuid, $txt$Matematika Kelas 2: Pengurangan$txt$, $txt$sch-sd-mat18-pengurangan$txt$, $txt$Materi pengurangan kelas 2 SD: pengertian, latihan benda konkret, pengurangan bersusun, contoh soal cerita, latihan, dan kunci jawaban.$txt$, 'id', 10, $txt$Madevi$txt$, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid, $txt$f7125028-187e-44e0-b95b-88b69b8d5c9a$txt$::uuid) ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Setelah belajar bab ini, siswa kelas 2 diharapkan mampu: (1) memahami pengurangan sebagai pengambilan sebagian, (2) melakukan pengurangan bilangan sampai 100 dengan cara bersusun, (3) menyelesaikan soal cerita pengurangan sederhana.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Pengurangan?$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Pengurangan artinya mengambil sebagian dari suatu jumlah. Lambangnya adalah tanda kurang (–). Contoh: Ibu punya 7 apel, dimakan 2, sisanya 7 – 2 = 5 apel.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $txt$Pengurangan dengan Benda Konkret$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', $txt$["Ambil 9 kelereng, berikan 4 kepada teman — hitung sisanya: 9 – 4 = 5", "Gambar 8 bintang di buku, coret 3 — sisanya 8 – 3 = 5", "Berlatihlah dengan jari, kancing, atau sedotan agar mudah membayangkan"]$txt$::jsonb));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $txt$Pengurangan Bersusun Pendek$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Untuk bilangan yang lebih besar, gunakan cara bersusun: tulis puluhan di atas puluhan dan satuan di atas satuan, lalu kurangi mulai dari satuan. Contoh: 45 – 23. Satuan: 5 – 3 = 2. Puluhan: 4 – 2 = 2. Hasilnya 22.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $txt$Contoh Soal Terpecahkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Di kelas ada 36 siswa. Sebanyak 14 siswa mengikuti lomba. Berapa siswa yang tidak mengikuti lomba? Jawab: 36 – 14. Satuan: 6 – 4 = 2. Puluhan: 3 – 1 = 2. Jadi, 22 siswa tidak mengikuti lomba.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', $txt$["Hitung: 27 – 12 = ... ; 58 – 25 = ... ; 90 – 40 = ...", "Siti punya 45 permen, diberikan 18 kepada adik. Berapa sisa permen Siti?", "Di pohon ada 63 mangga, dipetik 21. Berapa mangga yang masih di pohon?", "Kunci jawaban: (1) 15; 33; 50. (2) 45 – 18 = 27 permen. (3) 63 – 21 = 42 mangga."]$txt$::jsonb));
