-- Artikel batch 71 Madevi (idempoten, ON CONFLICT DO NOTHING)
BEGIN;

DO $do$ DECLARE v_id uuid; BEGIN
  SELECT id INTO v_id FROM madevi.articles WHERE business_code = $txt$TUT-BAHASA13-001$txt$;
  DELETE FROM madevi.article_blocks WHERE article_id = v_id;
END $do$;

